import * as rt from '@midnight-ntwrk/compact-runtime';
import { Contract, ledger, pureCircuits } from './out/contract/index.js';
const sk = (b)=>new Uint8Array(32).fill(b);
const mk = (b)=>new Contract({ secretKey: (ctx)=>[ctx.privateState, sk(b)] });
const A=pureCircuits.publicKey(sk(1)), B=pureCircuits.publicKey(sk(2));
const ca=mk(1), cb=mk(2);
const init = ca.initialState(rt.createConstructorContext({}, '0'.repeat(64)));
let ctx = rt.createCircuitContext(rt.dummyContractAddress(), init.currentZswapLocalState.coinPublicKey, init.currentContractState.data, init.currentPrivateState);
const show=(l)=>{const s=ledger(ctx.currentQueryContext.state);console.log(l,'supply',s.totalSupply,[...s.balances].map(([k,v])=>[Buffer.from(k).toString('hex').slice(0,6),v]));};
const call=(c,n,...a)=>{try{ctx=c.impureCircuits[n](ctx,...a).context;show(n)}catch(e){console.log(n,'FAILS:',e.message)}};
show('init');
call(cb,'mint',B,10n);      // non-admin
call(ca,'mint',B,100n);
call(cb,'transfer',A,30n);
call(cb,'transfer',A,500n); // too much
call(cb,'burn',20n);
call(cb,'burn',500n);
call(cb,'transfer',B,10n);  // self
console.log('balanceOf B', cb.impureCircuits.balanceOf(ctx,B).result, 'unknown', cb.impureCircuits.balanceOf(ctx,sk(9)).result);
EOF
